import { dataService } from '../../../../services/data/data_service'
import { dialogService } from '../../../../services/dialog_service'
import { useClaudeRateLimits } from '../../../hooks/use_claude_rate_limits'
import { useCodexRateLimits } from '../../../hooks/use_codex_rate_limits'
import { useProjectConfig } from '../../../hooks/use_project_config'
import { defaultScheduleAction } from '../popup/action_popup_defaults'
import type { ActionScheduleStore } from './action_schedule_store'
import { ActionScheduleForm, type ActionScheduleFormChange } from './action_schedule_form'
import { accountTrackerOptions, cardScheduleOptions, scheduleTargetStates } from './action_schedule_options'
import { canRegisterSchedule, createScheduleTrigger, type ActionScheduleTriggerSources } from './action_schedule_trigger'

const EMPTY_CARDS: ProjectSnapshot['activeCards'] = []

function subscribeActiveCards(listener: () => void) {
    dataService.addEventListener('changed', listener)

    return () => dataService.removeEventListener('changed', listener)
}

function getActiveCards() {
    return dataService.getState().snapshot?.activeCards ?? EMPTY_CARDS
}

interface ActionScheduleOwnerProps {
    action: ActionDefinition
    context: ActionContext
    store: ActionScheduleStore
}

/** Binds service-owned schedule form state to loaded runtime and project data. */
export function ActionScheduleOwner({ action, context, store }: ActionScheduleOwnerProps) {
    const snapshot = useSyncExternalStore(store.subscribe, store.getSnapshot, store.getSnapshot)
    const activeCards = useSyncExternalStore(subscribeActiveCards, getActiveCards, getActiveCards)
    const claudeState = useClaudeRateLimits()
    const codexState = useCodexRateLimits()
    const projectConfig = useProjectConfig()
    if (!snapshot.open) return null

    const sources: ActionScheduleTriggerSources = {
        accountTrackers: accountTrackerOptions(claudeState, codexState),
        cards: cardScheduleOptions(activeCards, context.cardInternalId),
        targetStates: scheduleTargetStates(projectConfig?.states),
    }
    const handleChange = (change: ActionScheduleFormChange) => {
        if (change.type === 'trigger-type') store.setTriggerType(change.triggerType)
        else if (change.type === 'timestamp') store.setTimestamp(change.timestamp)
        else if (change.type === 'agent') store.setAgent(change.agent)
        else if (change.type === 'tracker') store.setAccountTracker(change.limitId, change.windowId)
        else if (change.type === 'card') store.setCardInternalId(change.cardInternalId)
        else store.setTargetState(change.targetState)
    }
    const handleRegister = async () => {
        store.setMessage(null)
        try {
            const trigger = createScheduleTrigger(store.getSnapshot(), sources)
            await defaultScheduleAction(action, context, trigger)
            store.setMessage('Schedule registered')
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Could not register schedule' })
        }
    }

    return (
        <ActionScheduleForm
            accountTrackers={sources.accountTrackers}
            canRegister={canRegisterSchedule(snapshot, sources)}
            cards={sources.cards}
            message={snapshot.message}
            onChange={handleChange}
            onRegister={handleRegister}
            snapshot={snapshot}
            targetStates={sources.targetStates}
        />
    )
}

import type { ActionScheduleTrigger } from '../../../../data/action_schedule_types'
import type { ActionScheduleAccountTracker, ActionScheduleCardOption } from './action_schedule_options'
import type { ActionScheduleSnapshot } from './action_schedule_store'

export interface ActionScheduleTriggerSources {
    accountTrackers: ActionScheduleAccountTracker[]
    cards: ActionScheduleCardOption[]
    targetStates: string[]
}

function createAtScheduleTrigger(timestampInput: string, now: number): ActionScheduleTrigger {
    const timestamp = timestampInput.trim()
    if (timestamp.length === 0) throw new Error('Timestamp is required for time schedules')
    const fireAt = Date.parse(timestamp)
    if (Number.isNaN(fireAt)) throw new Error('Schedule timestamp is invalid')
    if (fireAt <= now) throw new Error('Schedule time must be in the future')

    return { timestamp: new Date(fireAt).toISOString(), type: 'at' }
}

function createAccountResetScheduleTrigger(
    snapshot: Extract<ActionScheduleSnapshot, { triggerType: 'account-reset' }>,
    accountTrackers: ActionScheduleAccountTracker[],
): ActionScheduleTrigger {
    if (!snapshot.agent) throw new Error('Agent is required for account reset schedules')
    const tracker = accountTrackers.find(({ agent, limitId, windowId }) => (
        agent === snapshot.agent && limitId === snapshot.limitId && windowId === snapshot.windowId
    ))
    if (!tracker) throw new Error('Selected account tracker is unavailable')
    if (!tracker.expectedResetAt) throw new Error('Selected account tracker has no reset time')

    return {
        agent: tracker.agent,
        expectedResetAt: tracker.expectedResetAt,
        limitId: tracker.limitId,
        type: 'account-reset',
        windowId: tracker.windowId,
    }
}

function createCardStateScheduleTrigger(
    snapshot: Extract<ActionScheduleSnapshot, { triggerType: 'card-state' }>,
    cards: ActionScheduleCardOption[],
    targetStates: string[],
): ActionScheduleTrigger {
    const card = cards.find(({ cardInternalId }) => cardInternalId === snapshot.cardInternalId)
    if (!card) throw new Error('Selected trigger card is unavailable')
    if (!card.registrationState) throw new Error('Selected trigger card has no current state')
    if (!targetStates.includes(snapshot.targetState)) throw new Error('Selected target state is unavailable')

    return {
        cardInternalId: card.cardInternalId,
        registrationState: card.registrationState,
        targetState: snapshot.targetState,
        type: 'card-state',
    }
}

/** Validate active schedule fields and build only selected trigger payload. */
export function createScheduleTrigger(
    snapshot: ActionScheduleSnapshot,
    sources: ActionScheduleTriggerSources,
    now = Date.now(),
): ActionScheduleTrigger {
    if (snapshot.triggerType === 'at') return createAtScheduleTrigger(snapshot.timestamp, now)
    if (snapshot.triggerType === 'account-reset') {
        return createAccountResetScheduleTrigger(snapshot, sources.accountTrackers)
    }

    return createCardStateScheduleTrigger(snapshot, sources.cards, sources.targetStates)
}

export function canRegisterSchedule(snapshot: ActionScheduleSnapshot, sources: ActionScheduleTriggerSources, now = Date.now()) {
    try {
        createScheduleTrigger(snapshot, sources, now)
        return true
    } catch {
        return false
    }
}

import type { Card, StateConfig } from '../../../../data/data_types'
import type { ClaudeRateLimitState } from '../../../../services/agents/claude_rate_limit_service'
import type { CodexRateLimitState } from '../../../../services/agents/codex_rate_limit_service'

const UNIX_MILLISECONDS_THRESHOLD = 1_000_000_000_000

export interface ActionScheduleAccountTracker {
    agent: 'claude' | 'codex'
    agentLabel: string
    expectedResetAt: string | null
    label: string
    limitId: string
    usedPercent: number
    windowId: string
}

export interface ActionScheduleCardOption {
    cardInternalId: string
    label: string
    registrationState: string | null
}

function resetTimestamp(agent: ActionScheduleAccountTracker['agent'], resetsAt: number | null) {
    if (resetsAt === null || !Number.isFinite(resetsAt)) return null
    const milliseconds = agent === 'codex' && resetsAt < UNIX_MILLISECONDS_THRESHOLD ? resetsAt * 1000 : resetsAt

    return new Date(milliseconds).toISOString()
}

/** Projects live provider snapshots into exact selectable account limit windows. */
export function accountTrackerOptions(
    claudeState: ClaudeRateLimitState,
    codexState: CodexRateLimitState,
): ActionScheduleAccountTracker[] {
    const trackers: ActionScheduleAccountTracker[] = []
    const claudeSnapshot = claudeState.snapshot
    if (!claudeState.stale && claudeState.receivedAt !== null && claudeSnapshot?.available) {
        trackers.push(...claudeSnapshot.windows.map((window) => ({
            agent: 'claude' as const,
            agentLabel: 'Claude',
            expectedResetAt: resetTimestamp('claude', window.resetsAt),
            label: `${window.id} Â· ${Math.round(window.usedPercent)}% used`,
            limitId: 'default',
            usedPercent: window.usedPercent,
            windowId: window.id,
        })))
    }

    const codexSnapshot = codexState.snapshot
    if (!codexState.stale && codexState.receivedAt !== null && codexSnapshot?.available) {
        for (const bucket of codexSnapshot.buckets) {
            const limitLabel = bucket.limitName?.trim() || bucket.limitId
            if (bucket.primary) {
                trackers.push({
                    agent: 'codex',
                    agentLabel: 'Codex',
                    expectedResetAt: resetTimestamp('codex', bucket.primary.resetsAt),
                    label: `${limitLabel} Â· primary Â· ${Math.round(bucket.primary.usedPercent)}% used`,
                    limitId: bucket.limitId,
                    usedPercent: bucket.primary.usedPercent,
                    windowId: 'primary',
                })
            }
            if (bucket.secondary) {
                trackers.push({
                    agent: 'codex',
                    agentLabel: 'Codex',
                    expectedResetAt: resetTimestamp('codex', bucket.secondary.resetsAt),
                    label: `${limitLabel} Â· secondary Â· ${Math.round(bucket.secondary.usedPercent)}% used`,
                    limitId: bucket.limitId,
                    usedPercent: bucket.secondary.usedPercent,
                    windowId: 'secondary',
                })
            }
        }
    }

    return trackers
}

/** Projects active cards into identity-safe schedule choices. Paths remain labels only. */
export function cardScheduleOptions(cards: Card[], currentCardInternalId: string | undefined): ActionScheduleCardOption[] {
    return cards
        .filter(({ header }) => !!header.internalId && header.internalId !== currentCardInternalId)
        .map(({ header, path }) => ({
            cardInternalId: header.internalId!,
            label: `${header.title} Â· ${path}`,
            registrationState: header.status,
        }))
}

export function scheduleTargetStates(states: StateConfig[] | undefined) {
    return states?.map(({ state }) => state) ?? []
}

